# collector.py - full working collector (auto-watch simulated file)\nimport os, time, json, logging\nfrom detector import process_event, init_db\nfrom datetime import datetime\nfrom watchdog.observers import Observer\nfrom watchdog.events import FileSystemEventHandler\nLOGFILE_LINUX = os.environ.get('LOG_PATH','/var/log/auth.log')\nSIM_FILE = os.environ.get('SIM_FILE','simulated_logs.jsonl')\nlogging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(message)s')\nlogger = logging.getLogger('collector')\ndef process_sim_file(path):\n    logger.info('Processing simulated logs: %s', path)\n    try:\n        with open(path,'r') as f:\n            for line in f:\n                try:\n                    evt = json.loads(line)\n                    if 'time' not in evt:\n                        evt['time'] = datetime.utcnow().isoformat()\n                    process_event(evt)\n                except Exception:\n                    logger.exception('Bad line in simulated file')\n    except Exception:\n        logger.exception('Failed to read simulated file')\nclass SimHandler(FileSystemEventHandler):\n    def __init__(self, path):\n        self.path = path\n    def on_modified(self, event):\n        if event.src_path.endswith(self.path):\n            logger.info('Detected change in simulated logs, processing...')\n            process_sim_file(self.path)\nif __name__ == '__main__':\n    init_db()\n    if not os.path.exists(SIM_FILE):\n        sample = [\n            {"type":"auth_failed","src":"192.168.1.10","message":"Failed password for invalid user"},\n            {"type":"auth_failed","src":"192.168.1.10","message":"Failed password for invalid user"},\n            {"type":"auth_failed","src":"192.168.1.10","message":"Failed password for invalid user"},\n            {"type":"auth_failed","src":"192.168.1.10","message":"Failed password for invalid user"},\n            {"type":"auth_failed","src":"192.168.1.10","message":"Failed password for invalid user"},\n            {"type":"port_scan","src":"192.168.1.20","ports":[22,80,443]},\n            {"type":"traffic_spike","bytes":12345678}\n        ]\n        with open(SIM_FILE,'w') as f:\n            for s in sample:\n                f.write(json.dumps(s) + "\\n")\n        logger.info('Wrote sample simulated file: %s', SIM_FILE)\n    event_handler = SimHandler(SIM_FILE)\n    observer = Observer()\n    observer.schedule(event_handler, path='.', recursive=False)\n    observer.start()\n    logger.info('Watching %s for changes. Append events to this file to trigger processing.', SIM_FILE)\n    try:\n        while True:\n            time.sleep(1)\n    except KeyboardInterrupt:\n        observer.stop()\n    observer.join()